// Arduino Mega 2560 + FS1264R (64 канала, GPIO Switch) + OLED 128x64 I2C
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

Adafruit_SSD1306 display(128, 64, &Wire, -1);
#define OLED_ADDR 0x3C   // если не взлетит — 0x3D

// Бит 0..5 = S1, S2, S3, CS1, CS2, CS3
const uint8_t CH_PINS[6] = {30, 31, 32, 33, 34, 35};

const uint8_t BTN_UP   = 2;   // кнопки на GND
const uint8_t BTN_DOWN = 3;
const uint8_t BTN_SCAN = 4;
const uint8_t RSSI_PIN = A0;

const uint16_t FREQ[8][8] = {
  {1920, 1960, 2000, 2040, 2080, 2120, 2160, 2200}, // FR1
  {1900, 1940, 1980, 2020, 2060, 2100, 2140, 2180}, // FR2
  {1740, 1760, 1780, 1800, 1820, 1840, 1860, 1880}, // FR3
  {1720, 1740, 1760, 1780, 1800, 1820, 1840, 1860}, // FR4
  {1420, 1460, 1500, 1540, 1580, 1620, 1660, 1700}, // FR5
  {1400, 1440, 1480, 1520, 1560, 1600, 1640, 1680}, // FR6
  {1100, 1140, 1180, 1220, 1260, 1300, 1340, 1380}, // FR7
  {1080, 1120, 1160, 1200, 1240, 1280, 1320, 1360}, // FR8
};

uint8_t channel = 0;
uint8_t lastU = HIGH, lastD = HIGH, lastS = HIGH;
int rssi = 0;
unsigned long tRssi = 0;

void setChannel(uint8_t ch) {
  channel = ch & 0x3F;
  for (uint8_t i = 0; i < 6; i++) {
    if ((channel >> i) & 1) pinMode(CH_PINS[i], INPUT);
    else { pinMode(CH_PINS[i], OUTPUT); digitalWrite(CH_PINS[i], LOW); }
  }
  draw();
}

uint16_t freqOf(uint8_t ch) { return FREQ[ch / 8][ch % 8]; }

void draw() {
  display.clearDisplay();
  display.setTextColor(SSD1306_WHITE);

  char buf[24];

  display.setTextSize(3);
  display.setCursor(0, 0);
  sprintf(buf, "CH %02u", channel + 1);
  display.print(buf);

  display.setTextSize(1);
  display.setCursor(0, 30);
  sprintf(buf, "FR%u  CH%u", channel / 8 + 1, channel % 8 + 1);
  display.print(buf);

  display.setCursor(0, 42);
  sprintf(buf, "%u MHz", freqOf(channel));
  display.print(buf);

  display.setCursor(0, 52);
  sprintf(buf, "RSSI %4d", rssi);
  display.print(buf);
  int bar = map(rssi, 0, 1023, 0, 60);
  display.drawRect(64, 52, 60, 9, SSD1306_WHITE);
  display.fillRect(65, 53, bar > 0 ? bar - 1 : 0, 7, SSD1306_WHITE);
  display.display();
}

void setup() {
  Serial.begin(115200);
  for (uint8_t i = 0; i < 6; i++) pinMode(CH_PINS[i], INPUT);
  pinMode(BTN_UP, INPUT_PULLUP);
  pinMode(BTN_DOWN, INPUT_PULLUP);
  pinMode(BTN_SCAN, INPUT_PULLUP);
  if (!display.begin(SSD1306_SWITCHCAPVCC, OLED_ADDR)) {
    Serial.println(F("OLED not found")); for (;;);
  }
  setChannel(0);
}

void loop() {
  uint8_t u = digitalRead(BTN_UP), d = digitalRead(BTN_DOWN), s = digitalRead(BTN_SCAN);
  static unsigned long tU = 0, tD = 0, tS = 0;
  if (u == LOW && lastU == HIGH && millis() - tU > 150) { setChannel((channel + 1) & 0x3F); tU = millis(); }
  if (d == LOW && lastD == HIGH && millis() - tD > 150) { setChannel((channel - 1) & 0x3F); tD = millis(); }
  if (s == LOW && lastS == HIGH && millis() - tS > 300) { scan(); tS = millis(); }
  lastU = u; lastD = d; lastS = s;

  if (millis() - tRssi > 100) { tRssi = millis(); rssi = analogRead(RSSI_PIN); draw(); }

  if (Serial.available()) {
    String cmd = Serial.readStringUntil('\n'); cmd.trim();
    if (cmd == "scan") scan();
    else { long c = cmd.toInt(); if (c >= 1 && c <= 64) setChannel(c - 1); }
  }
}

void scan() {
  uint8_t best = channel; int bestR = -1;
  display.clearDisplay(); display.setTextSize(2); display.setCursor(0, 24);
  display.print("Scanning..."); display.display();
  for (uint8_t c = 0; c < 64; c++) {
    setChannel(c);
    delay(80);
    int r = analogRead(RSSI_PIN);
    if (r > bestR) { bestR = r; best = c; }
  }
  setChannel(best);
  Serial.print(F("Best CH: ")); Serial.print(best + 1);
  Serial.print(F(" @ ")); Serial.print(freqOf(best)); Serial.println(F(" MHz"));
}
